/** Hand-written Logical Reasoning questions (original content). */
import type { RawItem, RawQ } from "../../types";
import { m, m2, m3, set } from "../build";

export const ASSUMPTION = ["Only assumption I is implicit", "Only assumption II is implicit", "Either I or II is implicit", "Neither I nor II is implicit", "Both I and II are implicit"];
export const CONCLUSION = ["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither I nor II follows", "Both I and II follow"];
export const ACTION = ["Only course of action I follows", "Only course of action II follows", "Either I or II follows", "Neither I nor II follows", "Both I and II follow"];
export const ARGUMENT = ["Only argument I is strong", "Only argument II is strong", "Either I or II is strong", "Neither I nor II is strong", "Both I and II are strong"];
export const CAUSE = [
  "Statement I is the cause and statement II is its effect",
  "Statement II is the cause and statement I is its effect",
  "Both the statements I and II are independent causes",
  "Both the statements I and II are effects of independent causes",
  "Both the statements I and II are effects of some common cause",
];
const F = { only1: 0, only2: 1, either: 2, neither: 3, both: 4 } as const;
type Five = keyof typeof F;
const five = (opts: string[]) => (q: string, ans: Five, e: string, d: 1 | 2 | 3 = 2): RawQ => ({ q, o: opts, a: F[ans], e, d });
const assume = five(ASSUMPTION), conclude = five(CONCLUSION), act = five(ACTION), argue = five(ARGUMENT);
const cause = (i: string, ii: string, ans: number, e: string, d: 1 | 2 | 3 = 2): RawQ => ({ q: `I. ${i}\nII. ${ii}`, o: CAUSE, a: ans, e, d });

