// ───────────── Verbal Reasoning (three-statement logic) ─────────────
const TFU = ["true", "false", "uncertain"];
const vr = (s: string, ans: 0 | 1 | 2, e: string, d: 1 | 2 | 3 = 1): RawQ => ({ q: `${s}\nIf the first two statements are true, the third statement is`, o: TFU, a: ans, e, d });
export const verbalReasoning: RawQ[] = [
  vr("All the trees in the park are flowering trees. Some of the trees in the park are dogwoods. All dogwoods in the park are flowering trees.", 0, "Every tree in the park is a flowering tree, and the dogwoods are trees in the park, so they must be flowering trees: **true**."),
  vr("Mara runs faster than Gail. Lily runs faster than Mara. Gail runs faster than Lily.", 1, "Lily > Mara > Gail, so Gail cannot be faster than Lily: **false**."),
  vr("Apartments in the Rivertown building cost more than those in the Hillside building. Apartments in the Lakeview building cost more than those in Rivertown. Hillside apartments cost more than Lakeview apartments.", 1, "Lakeview > Rivertown > Hillside, so the third statement is **false**."),
  vr("Every one of the students who passed the test studied in the library. Kiran studied in the library. Kiran passed the test.", 2, "Everyone who passed studied in the library, but studying in the library does not guarantee passing. Kiran's result is **uncertain**."),
  vr("All the offices on the 9th floor have wall-to-wall carpet. No wall-to-wall carpet is pink. None of the offices on the 9th floor has pink wall-to-wall carpet.", 0, "The 9th-floor carpets are wall-to-wall and no wall-to-wall carpet is pink, so **true**."),
  vr("The red book is heavier than the green book. The blue book is lighter than the green book. The red book is heavier than the blue book.", 0, "Red > green > blue in weight, so **true**."),
  vr("All the employees of ABC Ltd. know Excel. Some employees of ABC Ltd. know Python. Everyone who knows Python works at ABC Ltd.", 2, "The statements say nothing about Python users outside ABC Ltd., so the third statement is **uncertain**."),
  vr("Battery A lasts longer than battery B. Battery C lasts longer than battery B. Battery A lasts longer than battery C.", 2, "Both A and C last longer than B, but they are not compared with each other: **uncertain**.", 2),
  vr("No cats are allowed in the building. Tom's pet is a cat. Tom's pet is allowed in the building.", 1, "No cat is allowed and Tom's pet is a cat, so it is not allowed: **false**."),
  vr("Some musicians are teachers. All teachers are graduates. Some musicians are graduates.", 0, "The musicians who are teachers are graduates, so some musicians are graduates: **true**.", 2),
  vr("Store X opens before store Y. Store Z opens before store X. Store Y opens before store Z.", 1, "Z opens before X, which opens before Y. So Y opens after Z: **false**."),
  vr("All roses in the garden are red. Some flowers in the garden are roses. All flowers in the garden are red.", 2, "Only the roses are known to be red; other flowers may be any colour: **uncertain**.", 2),
];

